{
  "IP": "neorv32_debug_dm",
  "Conceptual Assets": [
    {
      "Concept ID": "C1",
      "Concept Name": "Debug authentication validity",
      "Unit": "neorv32_debug_dm",
      "Information": "The authentication-valid state determines whether debug accesses and hart-control outputs are enabled. It is produced by the optional authenticator rather than carried as a data value directly from a unit input.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The authenticator produces auth.valid at line 745, or ties it active when authentication is disabled at line 754, and the state controls authenticated access and hart-control behavior at lines 212-213, 500 and 505, so corruption can compromise authorization integrity.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could influence the authentication exchange or validity path to make an unauthenticated requester appear valid or to hold the module permanently invalid, respectively granting unauthorized debug control or denying authorized operation.",
      "Enters Through": [],
      "Leaves Through": [
        "dmi_rsp_o.data"
      ],
      "Entry Lines": [],
      "Held Lines": [
        745,
        754
      ],
      "Exit Lines": [
        549
      ]
    },
    {
      "Concept ID": "C2",
      "Concept Name": "Selected hart",
      "Unit": "neorv32_debug_dm",
      "Information": "The selected-hart setting identifies which hart receives debug control requests and whose status is reported. Debug operation depends on applying commands and status accesses to the intended hart.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "A DMI write stores the hart-selection value at line 429, and the resulting selection drives hart targeting through lines 487 and 500, so unauthorized modification can redirect debug control to another hart.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could write a different hart selection so halt, resume, reset-status, or debug operations affect the wrong hart and fail to control the intended one.",
      "Enters Through": [
        "dmi_req_i.data"
      ],
      "Leaves Through": [
        "dmi_rsp_o.data"
      ],
      "Entry Lines": [
        429
      ],
      "Held Lines": [
        429
      ],
      "Exit Lines": [
        562
      ]
    },
    {
      "Concept ID": "C3",
      "Concept Name": "Hart debug data",
      "Unit": "neorv32_debug_dm",
      "Information": "The data-register contents are words exchanged with a hart during abstract debug accesses. Abstract reads and writes depend on retaining this data between DMI or bus accesses and the hart-side debug transfer.",
      "Rubric": {
        "Confidentiality": "yes",
        "Integrity": "yes",
        "Availability": "no",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The data register is returned through both debug response paths at lines 605 and 696, so data placed in it can be exposed at the integration boundary.",
      "Rubric Reason": "The data register can be overwritten from DMI or bus input data at lines 666 and 668, allowing unauthorized modification of a hart debug transfer.",
      "Objectives At Risk": [
        "C",
        "I"
      ],
      "Attack": "An attacker could read the data register through a DMI or bus response or overwrite it before a hart transfer, exposing or corrupting debugged data.",
      "Enters Through": [
        "dmi_req_i.data",
        "bus_req_i.data"
      ],
      "Leaves Through": [
        "dmi_rsp_o.data",
        "bus_rsp_o.data"
      ],
      "Entry Lines": [
        666,
        668
      ],
      "Held Lines": [
        654,
        666,
        668
      ],
      "Exit Lines": [
        605,
        696
      ]
    },
    {
      "Concept ID": "C4",
      "Concept Name": "Hart halt request",
      "Unit": "neorv32_debug_dm",
      "Information": "The halt request is the command asserted to stop the selected hart. Debug control depends on preserving and delivering this request to the hart-control boundary.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "DMI data writes the halt command state at line 426 and the selected, authenticated command drives halt_req_o at line 500, so unauthorized modification can assert or suppress hart halting.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could alter the debug control value or its gating conditions to halt an unintended hart or prevent the intended hart from being halted.",
      "Enters Through": [
        "dmi_req_i.data"
      ],
      "Leaves Through": [
        "halt_req_o"
      ],
      "Entry Lines": [
        426
      ],
      "Held Lines": [
        500
      ],
      "Exit Lines": [
        500
      ]
    },
    {
      "Concept ID": "C5",
      "Concept Name": "Debug command busy state",
      "Unit": "neorv32_debug_dm",
      "Information": "The busy state indicates that the debug command controller is executing an abstract command. It gates acceptance of new command, program-buffer, data, and auto-execution accesses and is reported through debug status.",
      "Rubric": {
        "Confidentiality": "no",
        "Integrity": "yes",
        "Availability": "yes",
        "Undermined Expected Behavior": "no"
      },
      "Rubric Reason": "The busy state is produced from the command-controller state at line 339 and gates writes and command acceptance at lines 438, 443, 464 and 469, so an incorrect busy value can permit unsafe accesses or accept none.",
      "Rubric Reason": "The controller remains busy until the selected hart acknowledges completion at lines 305-306, so withholding or corrupting the completion path can block subsequent debug operations.",
      "Objectives At Risk": [
        "I",
        "A"
      ],
      "Attack": "An attacker could force the controller to appear idle during an active command or keep it busy by preventing completion, causing unsafe overlap or denial of later debug accesses.",
      "Enters Through": [],
      "Leaves Through": [
        "dmi_rsp_o.data"
      ],
      "Entry Lines": [],
      "Held Lines": [
        339
      ],
      "Exit Lines": [
        587
      ]
    }
  ],
  "Not Kept": [
    {
      "Candidate Name": "Selected-hart decode mask",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "C2",
      "Why Not Kept": ""
    },
    {
      "Candidate Name": "Authentication exchange data",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The debug-module rule bars authentication exchange words that only hold or decide what the debug ports deliver, so this is not a separate conceptual asset here."
    },
    {
      "Candidate Name": "Debug command word",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The command register is a debug-module command word used to sequence and report debug operations, and the debug-module rule bars it from being a piece of its own."
    },
    {
      "Candidate Name": "Program-buffer instructions",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The program-buffer words and their generated instruction copy only determine what the debug ports deliver to the hart, so the debug-module rule bars a separate concept for them."
    },
    {
      "Candidate Name": "Auto-execution and debug-control settings",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The auto-execution, active, and related debug-control register fields only gate or sequence debug-port operations and are barred by the debug-module rule."
    },
    {
      "Candidate Name": "Hart halt, resume, reset, and status bookkeeping",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The internal hart status, resume, reset, and acknowledgment fields only hold or report debug operations through the debug port and are not spared by the debug-module rule."
    },
    {
      "Candidate Name": "Command sequencing state and error status",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The state machine, illegal-command flags, and command-error status are sequencing or debug status information barred by the debug-module rule; the separately spared busy state is kept as C5."
    },
    {
      "Candidate Name": "Reset request and reset chain",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The ndmreset setting and ndmrstn_o only combine and pass a reset request, which the clocks-and-resets rule excludes from conceptual assets."
    },
    {
      "Candidate Name": "Authenticator busy status",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "Although a busy flag is spared for usual judgement, auth.busy is only reported at line 550 and does not gate, block, or alter a protected operation in this RTL, so no objective and violation mechanism support keeping it."
    },
    {
      "Candidate Name": "DMI and system-bus access transactions",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The access command fields and response handshakes only carry or qualify register and data accesses, so the access-command and transfer rules provide no independent conceptual asset."
    },
    {
      "Candidate Name": "Fixed debug instruction ROM",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "The instruction contents are a build-time constant at lines 149-182 that no runtime element can modify or withhold as a protected asset."
    },
    {
      "Candidate Name": "Clock and reset inputs",
      "Candidate Unit": "neorv32_debug_dm",
      "Merged Into": "",
      "Why Not Kept": "clk_i and rstn_i only time or reset the unit and its authenticator, and the clocks-and-resets rule excludes them."
    }
  ],
  "Notes": []
}
